void garbage_collect_keys(struct list_head *keys) {
    struct list_head *pos, *next;
    struct key *key;

    list_for_each_safe(pos, next, keys) {
        key = container_of(pos, struct key, list);
        list_del(&key->list);

        if (key->in_quota) {
            key->user->key_count--;
            key->user->quota_remaining++;
        }

        if (key->type->destroy) {
            key->type->destroy(key);
        }

        free(key);
    }
}
